 static void Cleanup(){if(rt){rt.Release();Object.DestroyImmediate(rt);}if(image)Object.DestroyImmediate(image);if(stage.IsValid())EditorSceneManager.CloseScene(stage,true);SceneManager.SetActiveScene(original);for(int i=0;i<originalLights.Count;i++)if(originalLights[i])originalLights[i].enabled=lightEnabled[i];RenderSettings.ambientMode=ambientMode;RenderSettings.ambientSkyColor=ambientSky;RenderSettings.ambientEquatorColor=ambientEquator;RenderSettings.ambientGroundColor=ambientGround;RenderSettings.fog=fog;RenderSettings.skybox=skybox;foreach(var o in temporary)if(o)Object.DestroyImmediate(o);temporary.Clear();materials.Clear();textMaterials.Clear();}
